import React, { useRef, useEffect, useState } from "react";
import { HERO_LABELS, BRAND } from "./Content";
import { ArrowDownRight, Sparkles, Crown, Gem, Truck } from "lucide-react";

export default function Hero({ onOpenQuote }) {
  const [activeLabel, setActiveLabel] = useState(null);

  useEffect(() => {
    const handleMouseMove = (e) => {
      const section = e.currentTarget;
      const rect = section.getBoundingClientRect();
      const nx = ((e.clientX - rect.left) / rect.width) * 100;
      const ny = ((e.clientY - rect.top) / rect.height) * 100;

      let best = null;
      let bestDist = Infinity;
      HERO_LABELS.forEach((l) => {
        const dx = l.x - nx;
        const dy = l.y - ny;
        const d = dx * dx + dy * dy;
        if (d < bestDist) { bestDist = d; best = l; }
      });
      if (bestDist < 35 * 35) setActiveLabel(best);
      else setActiveLabel(null);
    };

    const section = document.getElementById('hero-section');
    if (section) {
      section.addEventListener('mousemove', handleMouseMove);
      section.addEventListener('mouseleave', () => setActiveLabel(null));
    }
    return () => {
      if (section) {
        section.removeEventListener('mousemove', handleMouseMove);
      }
    };
  }, []);

  return (
    <section id="hero-section" className="relative w-full" style={{ background: "#ffffff" }}>

      {/* TOP SECTION - Wedding Image with Content */}
      <div className="relative w-full overflow-hidden" style={{ height: "65vh", minHeight: 450 }}>

        {/* Background Image - Using reliable Pexels images */}
        <div
          className="absolute inset-0"
          style={{
            backgroundImage: "url('https://images.pexels.com/photos/36547498/pexels-photo-36547498.jpeg?auto=compress&cs=tinysrgb&w=1920&h=1080&fit=crop')",
            backgroundSize: "cover",
            backgroundPosition: "center",
            backgroundRepeat: "no-repeat"
          }}
        />

        {/* Dark Overlay for text readability */}
        <div className="absolute inset-0" style={{ background: "rgba(26,8,10,0.45)" }} />

        {/* Gold Border Top */}
        <div className="absolute top-0 left-0 w-full h-1" style={{ background: "linear-gradient(90deg, transparent 0%, #d4af37 50%, transparent 100%)" }} />

        {/* Hero Content OVER Image */}
        <div className="absolute inset-0 flex flex-col justify-center px-8 md:px-16 lg:px-24">
          <div className="max-w-4xl">

            {/* Location Badge */}
            <div className="flex items-center gap-3 mb-4">
              <div className="w-12 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
              <span className="text-xs tracking-[0.3em] uppercase font-semibold" style={{ color: "#d4af37" }}>Ludhiana, Punjab | Pan India Delivery</span>
            </div>

            {/* Main Title */}
            <h1 className="serif leading-none tracking-tight mb-3" style={{ fontSize: "clamp(52px, 10vw, 130px)", fontWeight: 400, color: "#ffffff", textShadow: "0 4px 30px rgba(0,0,0,0.3)" }}>
              D SAJAWAT
            </h1>

            {/* Tagline */}
            <div className="flex items-center gap-3 mb-4">
              <Crown size={22} color="#d4af37" />
              <p className="serif text-lg md:text-2xl" style={{ color: "#f7e7ce", fontStyle: "italic", fontWeight: 400 }}>
                {BRAND.tagline}
              </p>
            </div>

            {/* Subtitle */}
            <p className="text-sm md:text-base max-w-xl" style={{ color: "rgba(255,255,255,0.85)", lineHeight: 1.6 }}>
              Premium fabrics for weddings & events. Trusted by India's top decorators.
            </p>
          </div>
        </div>

        {/* Hover Labels */}
        {HERO_LABELS.map((label) => (
          <div
            key={label.id}
            className="absolute transition-all duration-300 pointer-events-none"
            style={{
              left: `${label.x}%`,
              top: `${label.y}%`,
              transform: "translate(-50%, -50%)",
              opacity: activeLabel?.id === label.id ? 1 : 0,
              zIndex: 30,
            }}
          >
            <div className="px-5 py-2 rounded-full text-sm font-semibold whitespace-nowrap" style={{ background: "#d4af37", color: "#ffffff", boxShadow: "0 4px 20px rgba(212,175,55,0.5)" }}>
              {label.title}
            </div>
          </div>
        ))}

        {/* Bottom Gradient */}
        <div className="absolute bottom-0 left-0 w-full h-20" style={{ background: "linear-gradient(to bottom, transparent, #ffffff)" }} />
      </div>

      {/* BOTTOM CONTENT SECTION - Below Image */}
      <div className="relative w-full px-8 md:px-16 lg:px-24 py-12 md:py-16" style={{ background: "#ffffff" }}>

        {/* CTA Buttons - Centered */}
        <div className="flex flex-wrap justify-center gap-4 mb-8">
          <a href="#collections" className="btn-gold text-base md:text-lg px-8 py-3">
            <Sparkles size={18} strokeWidth={1.6} />
            Explore Our Collection
          </a>
          <button onClick={onOpenQuote} className="btn-ghost text-base md:text-lg px-8 py-3" type="button">
            Get a Quote
            <ArrowDownRight size={18} strokeWidth={1.6} />
          </button>
        </div>

        {/* Features Pills */}
        <div className="flex flex-wrap justify-center gap-3 mb-8">
          <div className="flex items-center gap-2 px-4 py-2 rounded-full" style={{ background: "#fff9ed", border: "1px solid rgba(212,175,55,0.3)" }}>
            <Gem size={16} color="#d4af37" />
            <span className="text-sm font-medium" style={{ color: "#1a080a" }}>Premium Quality</span>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 rounded-full" style={{ background: "#fff9ed", border: "1px solid rgba(212,175,55,0.3)" }}>
            <Truck size={16} color="#d4af37" />
            <span className="text-sm font-medium" style={{ color: "#1a080a" }}>Pan India Delivery</span>
          </div>
          <div className="flex items-center gap-2 px-4 py-2 rounded-full" style={{ background: "#fff9ed", border: "1px solid rgba(212,175,55,0.3)" }}>
            <Crown size={16} color="#d4af37" />
